import { createHmac, timingSafeEqual } from 'node:crypto';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { FileStorage, signingWindow } from './file-storage.js';

// Keys are generated by the API: "<folder>/<id>/<uuid>.<extension>".
const KEY_PATTERN =
  /^[a-z]+\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(pdf|png|jpg|webp)$/i;

export interface SignedParams {
  key: string;
  expires: number;
  name?: string;
}

// Stores files on the local disk. For development and tests, where there is
// no object storage account: it behaves like S3Storage, including signed
// links that expire, served by LocalFilesController. Not for production:
// container disks are wiped on every deploy and are not backed up.
export class LocalStorage implements FileStorage {
  constructor(
    private readonly directory: string,
    private readonly publicApiUrl: string,
    private readonly secret: string,
  ) {}

  async put(key: string, body: Buffer): Promise<void> {
    const path = this.pathOf(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, body);
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathOf(key), { force: true });
  }

  signedUrl(key: string, downloadName?: string): Promise<string> {
    const { expires } = signingWindow();
    const params = new URLSearchParams({ key, expires: String(expires) });
    if (downloadName) {
      params.set('name', downloadName);
    }
    params.set('signature', this.sign({ key, expires, name: downloadName }));
    return Promise.resolve(`${this.publicApiUrl}/api/files?${params}`);
  }

  // The absolute path of a valid, unexpired signed link; null otherwise.
  verify(params: SignedParams, signature: string): string | null {
    if (
      !Number.isInteger(params.expires) ||
      params.expires < Date.now() / 1000
    ) {
      return null;
    }
    const expected = Buffer.from(this.sign(params));
    const given = Buffer.from(signature);
    if (expected.length !== given.length || !timingSafeEqual(expected, given)) {
      return null;
    }
    return this.pathOf(params.key);
  }

  private sign({ key, expires, name }: SignedParams): string {
    return createHmac('sha256', this.secret)
      .update(`${key}\n${expires}\n${name ?? ''}`)
      .digest('base64url');
  }

  // Rejects anything that is not a key the API generates, so a request can
  // never reach a file outside the storage directory.
  private pathOf(key: string): string {
    if (!KEY_PATTERN.test(key)) {
      throw new Error(`Invalid storage key: ${key}`);
    }
    const root = resolve(this.directory);
    const path = resolve(root, key);
    if (!path.startsWith(root + sep)) {
      throw new Error(`Invalid storage key: ${key}`);
    }
    return path;
  }
}
